// C implementation of vstodo cmdBranch header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_branch.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_branch.go.\n\n#ifndef VSTODO_C_CMD_BRANCH_H\n#define VSTODO_C_CMD_BRANCH_H\n\n// Handle branch operations.\n// Equivalent to Go cmdBranch function.\n// app — vstodo application context pointer\n// args — command arguments (create <branch>, list, delete <branch>)\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_branch(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_BRANCH_H